import type { File, Database, OutputFile, Context, Record } from '@servicenow/sdk-build-core'

export async function getOutput(
    database: Database,
    context: Omit<Context, 'self'>
): Promise<(File & { source: Record })[]> {
    const handledGuids = new Set<string>()
    const output: OutputFile[] = []

    for (const step of [
        // First pass, using plugins that explicitly handle certain records
        { mode: 'explicit', creatorOnly: false },

        // Second pass, using plugins that can handle any record
        { mode: 'catch-all', creatorOnly: false },
    ] as const) {
        for (const plugin of context.plugins.toArray()) {
            const result = await plugin.recordsToFiles({ ...step, database, context, handledGuids })
            if (result.success) {
                output.push(...result.value)
            }
        }
    }

    return output.map((file) => ({
        source: file.source,
        path: context.project.resolvePath(
            context.config.appOutputDir,
            file.ifDirectoryPackage ?? '',
            file.category,
            file.name
        ),
        content: file.content,
    }))
}
